CREATE DATABASE IF NOT EXISTS bartoli_mechanics_basket CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE bartoli_mechanics_basket;
CREATE TABLE IF NOT EXISTS admin_users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS teams (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(140) NOT NULL, city VARCHAR(100) NULL, is_home_team TINYINT(1) NOT NULL DEFAULT 0, is_demo TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS players (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, jersey_number TINYINT UNSIGNED NOT NULL DEFAULT 0, position ENUM('Playmaker','Guardia','Ala piccola','Ala grande','Centro') NOT NULL DEFAULT 'Guardia', height_cm SMALLINT UNSIGNED DEFAULT NULL, birth_year SMALLINT UNSIGNED DEFAULT NULL, nationality VARCHAR(80) DEFAULT 'Italiana', bio TEXT, points_avg DECIMAL(4,1) NOT NULL DEFAULT 0, rebounds_avg DECIMAL(4,1) NOT NULL DEFAULT 0, assists_avg DECIMAL(4,1) NOT NULL DEFAULT 0, fg_pct DECIMAL(5,2) NOT NULL DEFAULT 0, three_pct DECIMAL(5,2) NOT NULL DEFAULT 0, ft_pct DECIMAL(5,2) NOT NULL DEFAULT 0, image_url VARCHAR(500) NULL, is_demo TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS staff (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, role VARCHAR(100) NOT NULL, bio TEXT, image_url VARCHAR(500), sort_order INT NOT NULL DEFAULT 0, is_demo TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS matches (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, opponent_id INT UNSIGNED NOT NULL, home_team_id INT UNSIGNED NOT NULL, match_date DATETIME NOT NULL, is_home TINYINT(1) NOT NULL DEFAULT 1, venue VARCHAR(180) NOT NULL DEFAULT 'PalaSpada · Fossombrone', status ENUM('programmata','in_corso','terminata','rinviata') NOT NULL DEFAULT 'programmata', home_score SMALLINT UNSIGNED NULL, away_score SMALLINT UNSIGNED NULL, ticket_url VARCHAR(500) NULL, season VARCHAR(20) NOT NULL DEFAULT '2026/27', is_demo TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_match_opponent FOREIGN KEY(opponent_id) REFERENCES teams(id), CONSTRAINT fk_match_home FOREIGN KEY(home_team_id) REFERENCES teams(id), INDEX idx_match_date(match_date), INDEX idx_match_status(status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS player_stats (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, player_id INT UNSIGNED NOT NULL, season VARCHAR(20) NOT NULL, games_played SMALLINT UNSIGNED DEFAULT 0, points_avg DECIMAL(4,1) DEFAULT 0, rebounds_avg DECIMAL(4,1) DEFAULT 0, assists_avg DECIMAL(4,1) DEFAULT 0, steals_avg DECIMAL(4,1) DEFAULT 0, fg_pct DECIMAL(5,2) DEFAULT 0, three_pct DECIMAL(5,2) DEFAULT 0, ft_pct DECIMAL(5,2) DEFAULT 0, is_demo TINYINT(1) DEFAULT 1, FOREIGN KEY(player_id) REFERENCES players(id) ON DELETE CASCADE, UNIQUE KEY uq_player_season(player_id,season)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS news (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(220) NOT NULL, category ENUM('Prima Squadra','Partite','Mercato','Giovanili','Società') NOT NULL DEFAULT 'Società', excerpt VARCHAR(500) NOT NULL, body MEDIUMTEXT NOT NULL, image_url VARCHAR(500), published_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, is_demo TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_news_date(published_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS market_moves (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, player_name VARCHAR(120) NOT NULL, move_type ENUM('Acquisto','Conferma','Cessione','Prestito') NOT NULL, move_date DATE NOT NULL, description TEXT, origin_destination VARCHAR(180), season VARCHAR(20) NOT NULL DEFAULT '2026/27', is_demo TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sponsors (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(140) NOT NULL, category VARCHAR(100) NOT NULL DEFAULT 'Partner demo', description TEXT, logo_text VARCHAR(100), url VARCHAR(500), is_demo TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS social_links (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, platform VARCHAR(80) NOT NULL, url VARCHAR(500) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS site_settings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, setting_key VARCHAR(100) NOT NULL UNIQUE, setting_value TEXT, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS live_streams (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(200) NOT NULL, status ENUM('unavailable','scheduled','live') NOT NULL DEFAULT 'unavailable', video_url VARCHAR(500), scheduled_at DATETIME NULL, is_demo TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
